int count = 5;
float rating = 3.7;
bool animated = true; //Disable for manual rating;

float sdStar5(in vec2 p, in float r, in float rf)
{
    const vec2 k1 = vec2(0.809016994375, -0.587785252292);
    const vec2 k2 = vec2(-k1.x,k1.y);
    p.x = abs(p.x);
    p -= 2.0*max(dot(k1,p),0.0)*k1;
    p -= 2.0*max(dot(k2,p),0.0)*k2;
    p.x = abs(p.x);
    p.y -= r;
    vec2 ba = rf*vec2(-k1.y,k1.x) - vec2(0,1);
    float h = clamp( dot(p,ba)/dot(ba,ba), 0.0, r );
    return length(p-ba*h) * sign(p.y*ba.x-p.x*ba.y);
}

float starRound( in vec2 p,in float r, in float rf, in float rr )
{
  return sdStar5(p, r, rf) - rr;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   float blur = 7.5 / iResolution.y;
   rating = animated ? float(count) * fract(iTime / 2.) : rating;
   fragColor = vec4(1, 1, 1, 1);
   for(int i = 0; i < count; i++) {
        vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
        p.y += .01;
        p.x -= .5 * float(i);
        p.x += .25 * float(count - 1);
        p *= 5.;

        float d = starRound(p, 1., .55, .1);
        d = smoothstep(-blur, blur, -d);
        float t = clamp(0., 1., rating - float(i));
        if(p.x <= mix(-1.05, 1.05, t) && p.x >= -1.05) {
            fragColor = mix(fragColor, vec4(0.23, 0.51, 0.96, 1), d);
        }
        else {
            fragColor = mix(fragColor, vec4(0.8, 0.84, 0.88, 1), d);
        }

       }
}
